// Choose T = int[]; keep total allocation under 2048 bytes
std::size_t n = static_cast<std::size_t>(*FUZZ_PARAM(unsigned int) % 256); // <= 1020 bytes for int
try {
    auto mem = cpp20::make_unique_for_overwrite<int[]>(n);
    // Elements are indeterminate; overwrite all allocated elements to satisfy API contract
    for (std::size_t i = 0; i < n; ++i) {
        mem[i] = static_cast<int>(i);
    }
    // Drop mem at end of scope; no outputs to keep persistent
