import random
from typing import List

# Target data type: decimal-integer string (ASCII digits only, non-negative, no sign, no spaces)
# This buffer will be used by FUZZ_PARAM_STR() in the fuzzer and elsewhere the stub constructs
# its own strictly-decimal strings. We focus on producing interesting valid decimal strings
# that exercise boundaries, sizes, and value patterns while remaining valid.

_MAX_LEN = 4000  # keep under fuzzer 4096 guidance even with some overhead

def _rand_choice(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(len(items))]

def _make_repeated_digit(rng: random.Random, length: int) -> str:
    d = rng.randrange(10)
    # Avoid leading zeros for longer numbers sometimes; but allow occasionally to test leading zero handling
    if length > 1 and d == 0 and rng.random() < 0.7:
        d = rng.randrange(1, 10)
    return str(d) * length

def _make_increasing_sequence(rng: random.Random, length: int) -> str:
    # Produces sequences like 1234567890123... truncated to length, avoiding leading zero typically
    start = rng.randrange(1, 10) if length > 1 else rng.randrange(0, 10)
    seq = []
    cur = start
    for _ in range(length):
        seq.append(str(cur))
        cur = (cur + 1) % 10
    # If leading zero and length > 1, bump first digit to 1 to avoid ambiguous leading zeros sometimes
    if length > 1 and seq[0] == '0' and rng.random() < 0.7:
        seq[0] = '1'
    return ''.join(seq)

def _make_random_digits(rng: random.Random, length: int) -> str:
    if length <= 0:
        return "0"
    # First digit: avoid leading zero most of the time for multi-digit values
    first = str(rng.randrange(1, 10)) if length > 1 and rng.random() < 0.8 else str(rng.randrange(0, 10))
    rest = ''.join(str(rng.randrange(0, 10)) for _ in range(max(0, length - 1)))
    return first + rest if length >= 1 else rest

def _make_power_of_ten_minus_one(rng: random.Random, length: int) -> str:
    # e.g., 9, 99, 999... a classic boundary pattern
    if length <= 0:
        return "9"
    return '9' * length

def _make_near_limits(rng: random.Random) -> str:
    # Generate numbers near typical integer limits while remaining purely decimal
    candidates = []
    # 32-bit
    candidates.append("2147483647")  # INT_MAX
    candidates.append("2147483646")
    candidates.append("2147483648")  # one over INT_MAX
    # 64-bit
    candidates.append("9223372036854775807")  # LLONG_MAX
    candidates.append("9223372036854775806")
    candidates.append("9223372036854775808")  # one over LLONG_MAX
    # 64-bit unsigned near top but safe for conversion to ULL in stub (it generates its own)
    candidates.append("18446744073709551615")
    candidates.append("18446744073709551614")
    # Small edge cases
    candidates.extend(["0", "00", "00000000", "1", "9", "10", "99", "100", "101"])
    return _rand_choice(rng, candidates)

def _choose_length(rng: random.Random) -> int:
    # Bias towards interesting lengths: 1, 2, 9, 10, 18, 19, 20, large
    weighted = [
        1, 2, 3, 9, 10, 18, 19, 20, 21,
        rng.randrange(22, 64),
        rng.randrange(64, 256),
        rng.randrange(256, 1024),
        rng.randrange(1024, min(2048, _MAX_LEN)),
    ]
    # Occasionally pick very large within cap
    if rng.random() < 0.2:
        weighted.append(rng.randrange(2048, _MAX_LEN))
    return _rand_choice(rng, [str(x) for x in weighted])  # will convert back below

def _len_to_int(s: str) -> int:
    try:
        return int(s)
    except Exception:
        return 1

def _compose_segments(rng: random.Random) -> str:
    # Build a single decimal string using different construction strategies.
    # Note: must be continuous digits with no separators.
    strat = rng.random()
    if strat < 0.15:
        return _make_near_limits(rng)
    # Determine length first
    L = _len_to_int(_choose_length(rng))
    L = max(1, min(_MAX_LEN, L))

    # Mix patterns: repeated, increasing, random blocks
    patterns = []
    if strat < 0.35:
        patterns.append(_make_repeated_digit(rng, L))
    elif strat < 0.6:
        patterns.append(_make_increasing_sequence(rng, L))
    elif strat < 0.85:
        patterns.append(_make_power_of_ten_minus_one(rng, L))
    else:
        # Compose from chunks to create long but structured numbers
        remaining = L
        while remaining > 0:
            chunk = min(remaining, rng.randrange(1, min(64, remaining) + 1))
            choice = rng.random()
            if choice < 0.33:
                seg = _make_random_digits(rng, chunk)
            elif choice < 0.66:
                seg = _make_repeated_digit(rng, chunk)
            else:
                seg = _make_increasing_sequence(rng, chunk)
            patterns.append(seg)
            remaining -= len(seg)
    s = ''.join(patterns)
    # Ensure not empty and within limit
    if not s:
        s = "0"
    if len(s) > _MAX_LEN:
        s = s[:_MAX_LEN]
    # Ensure all digits and avoid leading zero for multi-digit most of the time
    if len(s) > 1 and s[0] == '0' and rng.random() < 0.8:
        s = '1' + s[1:]
    return s

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    s = _compose_segments(rng)
    # Final safety: must be only digits and non-empty
    if not s or any((ord(c) < 48 or ord(c) > 57) for c in s):
        s = "0"
    # Cap size
    if len(s) > _MAX_LEN:
        s = s[:_MAX_LEN]
    return s.encode('ascii')

import random
from typing import List

# This generator produces strictly valid signed/unsigned base-10 integer strings
# matching the constraints used by the StringToInteger fuzzer stub. It assembles
# several newline-separated integers that the fuzzer can consume via FUZZ_PARAM_STR
# or similar string sources. Each token is valid per the "signed decimal-integer string with optional sign" spec.
# Size limited to <= 4096 bytes.

DIGITS = "0123456789"

# Interesting integer magnitudes in decimal for 32-bit and 64-bit boundaries
INT_MAX = 2_147_483_647
INT_MIN = -2_147_483_648
ULL_MAX_DIV10 = 18_446_744_073_709_551_61  # slightly under 2^64-1 to keep within range like stub 4
LL_MAX_SAFE = 9_000_000_000_000_000_000     # under 2^63

EDGE_VALUES = [
    0,
    1,
    -1,
    9,
    10,
    99,
    100,
    12345,
    -12345,
    INT_MAX,
    INT_MIN,
    INT_MAX - 1,
    INT_MIN + 1,
    LL_MAX_SAFE,
]


def _rand_upto(rng: random.Random, n: int) -> int:
    if n <= 0:
        return 0
    return rng.randrange(n)


def _rand_decimal_of_size(rng: random.Random, digits: int) -> int:
    # Generate a non-negative integer with the specified number of decimal digits (no leading zeros unless digits==1)
    if digits <= 0:
        return 0
    first = rng.randrange(1, 10) if digits > 1 else rng.randrange(0, 10)
    val = first
    for _ in range(1, digits):
        val = val * 10 + rng.randrange(0, 10)
    return val


def _rand_bounded(rng: random.Random, lo: int, hi: int) -> int:
    return rng.randrange(lo, hi + 1) if hi >= lo else lo


def _format_signed(val: int, force_plus: bool = False) -> str:
    if val < 0:
        return "-" + str(-val)
    if force_plus:
        return "+" + str(val)
    return str(val)


def _make_token_signed_int(rng: random.Random) -> str:
    # Valid for int (with optional '-') within 32-bit range, strictly decimal
    neg = rng.choice([False, True])
    if neg:
        # avoid INT_MIN overflow in absolute; pick [1..INT_MAX]
        magnitude = _rand_bounded(rng, 1, INT_MAX)
        return _format_signed(-magnitude)
    else:
        return str(_rand_bounded(rng, 0, INT_MAX))


def _make_token_unsigned_with_plus_optional(rng: random.Random) -> str:
    # Valid for unsigned long long, optionally prefixed with '+'
    # Keep comfortably within the bound used by the stub (ULL_MAX_DIV10)
    v = _rand_bounded(rng, 0, ULL_MAX_DIV10)
    return _format_signed(v, force_plus=rng.choice([False, True]))


def _make_token_longlong(rng: random.Random) -> str:
    # Large positive number within 63-bit safe range
    v = _rand_bounded(rng, 0, LL_MAX_SAFE)
    return str(v)


def _make_edge_token(rng: random.Random) -> str:
    v = rng.choice(EDGE_VALUES)
    # Randomly force a plus sign for non-negative values to exercise optional '+' path
    if v >= 0 and rng.random() < 0.3:
        return "+" + str(v)
    return str(v)


def _make_random_length_number(rng: random.Random) -> str:
    # Produce random-length strictly-decimal number with optional leading sign (both valid)
    # length 1..20 digits, avoid leading zeros unless single digit
    digits = _rand_bounded(rng, 1, 20)
    val = _rand_decimal_of_size(rng, digits)
    # Optional sign; ensure '-' only when non-zero
    sign_choice = rng.random()
    if sign_choice < 0.33 and val != 0:
        return "-" + str(val)
    elif sign_choice < 0.66:
        return str(val)
    else:
        return "+" + str(val)


def _assemble_tokens(tokens: List[str]) -> bytes:
    # Join by newlines to offer multiple discrete values; ensure size cap
    data = "\n".join(tokens)
    # Truncate conservatively to 4096 bytes; avoid cutting mid-token by trimming to last newline within limit
    b = data.encode("ascii")
    if len(b) <= 4096:
        return b
    # find last newline before 4096
    cut = 4096
    idx = b.rfind(b"\n", 0, cut)
    if idx == -1:
        # fallback: just hard cut
        return b[:4096]
    return b[:idx]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    tokens: List[str] = []

    # Include a mix ensuring coverage for all paths the stub asserts on
    # 1) Signed int strings (with optional '-')
    for _ in range(3):
        tokens.append(_make_token_signed_int(rng))

    # 2) Unsigned with optional '+'
    for _ in range(3):
        tokens.append(_make_token_unsigned_with_plus_optional(rng))

    # 3) Long long large positives
    for _ in range(3):
        tokens.append(_make_token_longlong(rng))

    # 4) Edge values
    for _ in range(6):
        tokens.append(_make_edge_token(rng))

    # 5) Random length numeric tokens
    for _ in range(10):
        tokens.append(_make_random_length_number(rng))

    # Shuffle to diversify ordering
    rng.shuffle(tokens)

    return _assemble_tokens(tokens)

import random
import string
from typing import List

# Target data type: non-numeric string
# Fix: guard randint ranges to avoid empty ranges when max_len is small.

INVALID_PATTERNS: List[str] = [
    "a", "abc", "x123", "minus123", "plus99",
    "+", "-", "+x", "-x", "+ 1", "- 1",
    "12a", "007b", "1_000", "123,456", "12.3", "1e9", "0x10", "0b1010",
    " 1", "1 ", "\t2", "3\n", "  42 ",
    "--1", "++2", "+-3", "-+4",
    "()", "[1]", "{2}", "<3>", "#5",
    "NaN", "Inf", "Infinity",
    "123abc456", "09 nine", "eight 8", "_42",
]

DIGITS = string.digits
LOWER = string.ascii_lowercase
UPPER = string.ascii_uppercase
PUNCT = "!@#$%^&*()[]{}<>?/\\|~`_=:;,.\'\""
WS = " \t\n\r\f\v"
SIGNS = "+-"


def _rand_choice(rng: random.Random, seq: str) -> str:
    return seq[rng.randrange(len(seq))]


def _bounded_len(rng: random.Random, lo: int, hi: int) -> int:
    # Safe randint with clamping ensuring lo<=hi and >=1
    hi = max(lo, hi)
    return rng.randint(lo, hi)


def _make_alpha_leading(rng: random.Random, max_len: int) -> str:
    max_len = max(1, max_len)
    n = _bounded_len(rng, 1, max_len)
    s = [_rand_choice(rng, LOWER + UPPER)]
    for _ in range(n - 1):
        s.append(_rand_choice(rng, LOWER + UPPER + DIGITS))
    return "".join(s)


def _make_mixed_digits_letters(rng: random.Random, max_len: int) -> str:
    max_len = max(2, max_len)
    n = _bounded_len(rng, 2, max_len)
    s = []
    for i in range(n):
        if i == 0 and rng.random() < 0.5:
            s.append(_rand_choice(rng, LOWER + UPPER))
        else:
            s.append(_rand_choice(rng, LOWER + UPPER + DIGITS))
    if all(ch in DIGITS for ch in s):
        s[rng.randrange(n)] = _rand_choice(rng, LOWER + UPPER)
    return "".join(s)


def _make_with_punct_or_ws(rng: random.Random, max_len: int) -> str:
    max_len = max(2, max_len)
    n = _bounded_len(rng, 2, max_len)
    s = []
    for _ in range(n):
        pick = rng.random()
        if pick < 0.4:
            s.append(_rand_choice(rng, DIGITS))
        elif pick < 0.7:
            s.append(_rand_choice(rng, LOWER + UPPER))
        elif pick < 0.85:
            s.append(_rand_choice(rng, PUNCT))
        else:
            s.append(_rand_choice(rng, WS))
    s[rng.randrange(n)] = _rand_choice(rng, (LOWER + UPPER + PUNCT + WS))
    return "".join(s)


def _make_bad_sign(rng: random.Random, max_len: int) -> str:
    max_len = max(2, max_len)
    sign = _rand_choice(rng, SIGNS)
    mode = rng.randrange(3)
    if mode == 0:
        tail = _make_alpha_leading(rng, max(1, max_len - 1))
        return sign + tail
    elif mode == 1:
        # sign + space + digits
        digits_len_hi = max(1, max_len - 2)
        digits_len = _bounded_len(rng, 1, digits_len_hi)
        digits = "".join(_rand_choice(rng, DIGITS) for _ in range(digits_len))
        return sign + _rand_choice(rng, WS) + digits
    else:
        # digits + sign + letter
        digits_len_hi = max(1, (max_len - 2))
        digits_len = _bounded_len(rng, 1, digits_len_hi)
        digits = "".join(_rand_choice(rng, DIGITS) for _ in range(digits_len))
        return digits + sign + _rand_choice(rng, LOWER + UPPER)


def _make_prefixed_like_hex_or_bin(rng: random.Random, max_len: int) -> str:
    max_len = max(3, max_len)  # need room for prefix + at least 1 char
    base = rng.choice(["0x", "0X", "0b", "0B"])
    rest_hi = max(1, max_len - len(base))
    rest_len = _bounded_len(rng, 1, rest_hi)
    if base.lower().endswith("x"):
        alphabet = DIGITS + "abcdefABCDEF"
    else:
        alphabet = "01"
    rest = "".join(_rand_choice(rng, alphabet) for _ in range(rest_len))
    return base + rest


def _make_with_separators(rng: random.Random, max_len: int) -> str:
    max_len = max(3, max_len)
    sep = rng.choice([",", "_", ".", " "])
    parts = []
    groups = _bounded_len(rng, 2, max(2, max_len // 2))
    for _ in range(groups):
        part_len = _bounded_len(rng, 1, 3)
        parts.append("".join(_rand_choice(rng, DIGITS) for _ in range(part_len)))
    return sep.join(parts)[:max_len]


def _pick_invalid(rng: random.Random) -> str:
    if rng.random() < 0.6:
        max_len = _bounded_len(rng, 2, 64)
        maker = rng.choice([
            _make_alpha_leading,
            _make_mixed_digits_letters,
            _make_with_punct_or_ws,
            _make_bad_sign,
            _make_prefixed_like_hex_or_bin,
            _make_with_separators,
        ])
        s = maker(rng, max_len)
    else:
        s = rng.choice(INVALID_PATTERNS)
    if not s:
        s = "x"
    if s[0] in DIGITS + SIGNS:
        s = _rand_choice(rng, LOWER + UPPER + PUNCT.replace("+", "").replace("-", "")) + s[1:]
    return s[:256]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    mode = rng.randrange(4)
    if mode == 0:
        s = _pick_invalid(rng)
    elif mode == 1:
        left_ws = rng.choice([" ", "\t", "\n", "\r"]) * _bounded_len(rng, 1, 3)
        right_ws = rng.choice([" ", "\t", "\n"]) * _bounded_len(rng, 1, 3)
        s = left_ws + _pick_invalid(rng) + right_ws
    elif mode == 2:
        core = _pick_invalid(rng)
        insert = _rand_choice(rng, PUNCT)
        pos = rng.randrange(len(core) + 1)
        s = core[:pos] + insert + core[pos:]
    else:
        parts = [_pick_invalid(rng) for _ in range(_bounded_len(rng, 2, 4))]
        sep = rng.choice([" ", ",", ";", ":", "|"])
        s = sep.join(parts)
    s = s[:4096]
    return s.encode("utf-8", errors="replace")
